import heapq

def match(orders):
    trades = []
    book_buy = []   # heap of (-price, seq, id)
    book_sell = []  # heap of (price, seq, id)
    orders_info = {}  # id -> {'side':, 'qty': remaining, 'active': bool}

    for seq, order in enumerate(orders):
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in orders_info and orders_info[oid]['active']:
                orders_info[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        orders_info[oid] = {'side': side, 'qty': qty, 'active': False}

        if side == 'buy':
            opp_heap = book_sell
        else:
            opp_heap = book_buy

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                opp_price, opp_seq, opp_id = top
            else:
                neg_opp_price, opp_seq, opp_id = top
                opp_price = -neg_opp_price

            if opp_id not in orders_info or not orders_info[opp_id]['active']:
                heapq.heappop(opp_heap)
                continue

            opp_info = orders_info[opp_id]
            if opp_info['qty'] <= 0:
                orders_info[opp_id]['active'] = False
                heapq.heappop(opp_heap)
                continue

            if typ == 'market':
                price_ok = True
            else:
                if side == 'buy':
                    price_ok = price >= opp_price
                else:
                    price_ok = price <= opp_price

            if not price_ok:
                break

            trade_qty = min(remaining, opp_info['qty'])
            trade_price = opp_price

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            opp_info['qty'] -= trade_qty

            if opp_info['qty'] == 0:
                opp_info['active'] = False
                heapq.heappop(opp_heap)
            # else: incoming must be exhausted (remaining == 0), loop will end

        orders_info[oid]['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            orders_info[oid]['active'] = True
            if side == 'buy':
                heapq.heappush(book_buy, (-price, seq, oid))
            else:
                heapq.heappush(book_sell, (price, seq, oid))
        else:
            orders_info[oid]['active'] = False

    return trades

